'use strict';
(()=>{
const canvas=document.getElementById('sculpture'),button=document.getElementById('morph');
let gl;try{gl=canvas.getContext('webgl',{alpha:true,antialias:true,powerPreference:'low-power'});}catch{}
if(!gl){canvas.hidden=true;const fallback=document.createElement('div');fallback.className='sculpture-fallback';fallback.textContent='∞';canvas.after(fallback);button.textContent='Reshape the loop ↗';let turns=0;button.onclick=()=>{turns+=45;fallback.style.transform=`rotate(${turns}deg)`;};return;}
const vertex=`attribute vec3 position;attribute vec3 normal;uniform vec2 angle;uniform float aspect;varying vec3 vN;varying vec3 vP;void main(){float cx=cos(angle.x),sx=sin(angle.x),cy=cos(angle.y),sy=sin(angle.y);mat3 rx=mat3(1.,0.,0.,0.,cx,sx,0.,-sx,cx);mat3 ry=mat3(cy,0.,-sy,0.,1.,0.,sy,0.,cy);vec3 p=ry*rx*position;vN=ry*rx*normal;vP=p;float z=6.5-p.z;gl_Position=vec4(p.x*2.8/aspect,p.y*2.8,z*.8-1.,z);}`;
const fragment=`precision mediump float;varying vec3 vN;varying vec3 vP;uniform float material;void main(){vec3 n=normalize(vN);vec3 view=normalize(vec3(0.,0.,6.5)-vP);float fres=pow(1.-max(dot(n,view),0.),2.5);float key=max(dot(n,normalize(vec3(-1.,2.,3.))),0.);float band=pow(.5+.5*sin(n.y*10.+n.x*3.),8.);float spec=pow(max(dot(reflect(-normalize(vec3(-2.,3.,4.)),n),view),0.),55.);vec3 base=mix(vec3(.28,.32,.22),vec3(.51,.39,.67),material);vec3 color=base*(.2+key*.6)+vec3(.78,.83,.64)*band*.75+vec3(.95,.98,.84)*spec+vec3(.65,.76,.34)*fres*.65;gl_FragColor=vec4(color,1.);}`;
function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('Sculpture shader compilation failed');return s;}
const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vertex));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Sculpture shader linking failed');gl.useProgram(program);
const normalize=v=>{const l=Math.hypot(...v);return v.map(x=>x/l);},cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
function center(t,m){const r=1.16+.39*Math.cos(3*t);return [r*Math.cos(2*t),r*Math.sin(2*t),(.5+.15*m)*Math.sin(3*t)];}
const segments=240,sides=24,positions=[],normals=[],indices=[];
for(let i=0;i<=segments;i++){const t=i/segments*Math.PI*2,p=center(t,0),next=center(t+.001,0),tangent=normalize(next.map((v,j)=>v-p[j])),n=normalize(cross(tangent,[0,0,1])),b=cross(tangent,n);for(let j=0;j<=sides;j++){const a=j/sides*Math.PI*2,normal=n.map((v,k)=>v*Math.cos(a)+b[k]*Math.sin(a));positions.push(...p.map((v,k)=>v+normal[k]*.32));normals.push(...normal);if(i<segments&&j<sides){const v=i*(sides+1)+j;indices.push(v,v+1,v+sides+1,v+1,v+sides+2,v+sides+1);}}}
for(const [name,data] of [['position',positions],['normal',normals]]){const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(data),gl.STATIC_DRAW);const loc=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,3,gl.FLOAT,false,0,0);}
gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,gl.createBuffer());gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(indices),gl.STATIC_DRAW);gl.enable(gl.DEPTH_TEST);
const angle=gl.getUniformLocation(program,'angle'),aspect=gl.getUniformLocation(program,'aspect'),material=gl.getUniformLocation(program,'material');let x=.4,y=-.6,targetX=.4,targetY=-.6,twist=0,mat=0,targetMat=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,visible=true,time=0,last=0,frame=0;
function draw(){const ratio=Math.min(devicePixelRatio||1,1.75),w=Math.round(canvas.clientWidth*ratio),h=Math.round(canvas.clientHeight*ratio);if(!w||!h)return;if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;gl.viewport(0,0,w,h);}gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.uniform2f(angle,x,y);gl.uniform1f(aspect,w/h);gl.uniform1f(material,mat);gl.drawElements(gl.TRIANGLES,indices.length,gl.UNSIGNED_SHORT,0);}
function tick(now){frame=0;if(!visible||document.hidden)return;if(!paused){time+=Math.min((now-last)||16,40)*.00014;const scroll=Math.min(scrollY/1000,1);x+=(targetX+Math.sin(time)*.12+scroll*.5-x)*.045;y+=(targetY+twist+time*.18-y)*.045;mat+=(targetMat-mat)*.055;}last=now;draw();if(!paused)frame=requestAnimationFrame(tick);}
function request(){if(!frame)frame=requestAnimationFrame(tick);}
canvas.addEventListener('pointermove',e=>{if(paused)return;const r=canvas.getBoundingClientRect();targetX=.4+(e.clientY-r.top-r.height/2)/r.height*.8;targetY=-.6+(e.clientX-r.left-r.width/2)/r.width*1.1;request();});canvas.addEventListener('pointerleave',()=>{targetX=.4;targetY=-.6;});button.onclick=()=>{twist+=Math.PI*.65;targetMat=1-targetMat;if(paused){y=targetY+twist;mat=targetMat;draw();}else request();};window.addEventListener('motionchange',e=>{paused=e.detail;request();});new ResizeObserver(request).observe(canvas);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)request();else if(frame){cancelAnimationFrame(frame);frame=0;}}).observe(canvas);document.addEventListener('visibilitychange',()=>{if(!document.hidden)request();});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(frame)cancelAnimationFrame(frame);button.disabled=true;button.textContent='3D paused — reload to restore';});request();
})();
